<script lang="ts">
import {tick} from 'svelte';
import X from 'lucide-svelte/icons/x';
import {invoke} from '@tauri-apps/api/core';
import {updateSettings,type Settings} from '$lib/api';
import {applySuggestion,type ProofreadResult,type ProofreadMatch} from '$lib/proofreading';
let {text,onReplace,compact=false}:{compact?:boolean;text:string;onReplace:(next:string,checked:string)=>boolean|Promise<boolean>}=$props();
let report=$state<ProofreadResult|null>(null);let loading=$state(false);let error=$state('');let note=$state('');let ignored=$state<string[]>([]);let sequence=0;
const stale=$derived(!!report&&report.source!==text);const visible=$derived(report?.matches.filter(m=>!ignored.includes(m.id))||[]);
async function check(){const original=text;const token=++sequence;loading=true;error='';note='';ignored=[];try{const value=await invoke<ProofreadResult>('check_spelling',{text:original});if(token!==sequence)return;if(text!==original){report=null;note='Le texte a changé pendant la vérification. Relance-la.';return}if(!value.ok)throw Error(value.error||'Le correcteur est indisponible.');if(value.source!==original)throw Error('La réponse du correcteur ne correspond pas au texte.');report=value;if(value.matches.length===0)note='Aucune suggestion sur ce texte.'}catch(e){if(token===sequence)error=String(e)}finally{if(token===sequence)loading=false}}
async function accept(match:ProofreadMatch,value:string){if(!report)return;const checked=report.source;const next=applySuggestion(text,checked,match,value);if(next===null){report=null;note='Le texte a changé. Vérifie-le à nouveau.';return}if(!await onReplace(next,checked)){report=null;note='Le texte a changé. Aucune correction appliquée.';return}report=null;await tick();if(text===next)await check()}
async function addWord(match:ProofreadMatch){if(stale)return;error='';loading=true;try{const cfg=await invoke<Settings>('settings_get');const word=match.original.trim();if(!word||word.length>64)throw Error('Choisis une expression de 64 caractères maximum.');const words=Array.from(new Set([...(cfg.personal_words||[]),word]));await updateSettings({personal_words:words});loading=false;await check()}catch(e){error=String(e);loading=false}}
</script>
<div class="proofreader" class:compact>
<div class="proofread-heading"><button class="btn" disabled={loading||!text.trim()||Array.from(text).length>20000} onclick={check}>{loading?'Vérification locale…':'Vérifier le texte'}</button><span title="Grammalecte · français · hors ligne">{compact?'Correction locale':'Grammalecte · français · hors ligne'}</span>{#if report}<button class="dismiss" aria-label="Fermer les suggestions" onclick={()=>report=null}><X size={18} aria-hidden="true"/></button>{/if}</div>
{#if Array.from(text).length>20000}<p class="info">La vérification est limitée à 20 000 caractères par texte.</p>{/if}
{#if error}<p class="problem" role="alert">{error}</p>{/if}{#if note}<p class="info" role="status">{note}</p>{/if}
{#if stale}<p class="info" role="status">Le texte a changé. Relance la vérification pour avoir des suggestions à jour.</p>
{:else if report&&visible.length}<div class="suggestions" aria-label="Suggestions de correction">{#each visible as match (match.id)}<article><p><strong>{match.original||'Ponctuation'}</strong><span>{match.message}</span></p><div class="suggestion-actions">{#each match.suggestions.slice(0,4) as suggestion}<button class="btn" disabled={loading} onclick={()=>accept(match,suggestion)}>Accepter « {suggestion||'retirer'} »</button>{/each}<button class="btn ghost" disabled={loading} onclick={()=>ignored=[...ignored,match.id]}>Ignorer</button>{#if match.original.trim()&&match.original.length<=64}<button class="btn ghost" disabled={loading} onclick={()=>addWord(match)}>Ajouter au lexique</button>{/if}</div></article>{/each}</div>{:else if report&&!visible.length&&!note}<p class="info">Toutes les suggestions ont été traitées.</p>{/if}
</div>
<style>
.proofreader{border-top:1px solid var(--border);background:var(--surface);padding:10px 16px;flex:none;max-height:40vh;overflow:auto}.proofread-heading{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.proofread-heading>span{font-size:12px;color:var(--muted)}.proofread-heading .btn{min-height:40px}.dismiss{margin-left:auto;min-width:40px;min-height:40px;border:0;background:none;color:var(--muted);font-size:24px}.info,.problem{font-size:12px;line-height:1.6;margin:8px 0}.info{color:var(--muted)}.problem{color:var(--danger)}.suggestions article{border-top:1px solid var(--border);padding:12px 0}.suggestions p{display:flex;gap:8px;flex-wrap:wrap;font-size:13px;line-height:1.5;margin:0 0 8px}.suggestions p span{color:var(--muted)}.suggestion-actions{display:flex;flex-wrap:wrap;gap:6px}.suggestion-actions .btn{min-height:40px;font-size:12px}
.compact{padding:4px 8px;max-height:40%;scrollbar-width:thin;scrollbar-color:var(--border) transparent}.compact .proofread-heading{gap:6px}.compact .proofread-heading>.btn{min-height:36px;font-size:12px;padding:5px 8px}.compact .proofread-heading>span{font-size:11px}.compact .dismiss{display:grid;place-items:center;min-width:32px;min-height:36px;padding:0}
</style>
